from django.core.management.base import BaseCommand, CommandError


class Command(BaseCommand):
    help = "Run automated maintenance checks and report active records."

    def add_arguments(self, parser) -> None:
        parser.add_argument("--tier", choices=["flash", "pro", "advance"], default="flash")
        parser.add_argument("--dry-run", action="store_true")

    def handle(self, *args, **options) -> None:
        tier = options["tier"]
        if not tier:
            raise CommandError("Tier is required.")
        mode = "DRY-RUN" if options["dry_run"] else "EXECUTE"
        self.stdout.write(self.style.SUCCESS(f"[{mode}] Completed task for tier={tier}"))

