from fastapi import APIRouter
from pydantic import BaseModel, Field
from starlette.concurrency import run_in_threadpool

router = APIRouter(prefix="/api/v1/compute", tags=["Compute"])


class ComputeRequest(BaseModel):
    prompt: str = Field(..., min_length=1, max_length=16000)
    tier: str = Field(default="flash", pattern="^(flash|pro|advance)$")


def _cpu_heavy_work(prompt: str, tier: str) -> dict[str, object]:
    return {"tier": tier, "tokens": len(prompt.split()), "status": "completed"}


@router.post("/run")
async def run_compute(payload: ComputeRequest) -> dict[str, object]:
    return await run_in_threadpool(_cpu_heavy_work, payload.prompt, payload.tier)

