import numpy as np

def cross_entropy_loss(logits: np.ndarray, targets: np.ndarray) -> float:
    shifted = logits - logits.max(axis=1, keepdims=True)
    exp = np.exp(shifted)
    probs = exp / np.maximum(exp.sum(axis=1, keepdims=True), 1e-9)
    return float(-np.log(np.maximum(probs[np.arange(len(targets)), targets], 1e-8)).mean())

from pathlib import Path
import numpy as np

def save_weights_npz(path: Path, weights: dict[str, np.ndarray]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    np.savez_compressed(path, **{k: v.astype(np.float32) for k, v in weights.items()})

def load_weights_npz(path: Path) -> dict[str, np.ndarray]:
    with np.load(path, allow_pickle=False) as archive:
        return {k: np.asarray(archive[k], dtype=np.float32) for k in archive.files}

